CREATE COLUMN TABLE "TEST_AP"."OCYC" ("Code" SMALLINT CS_INT NOT NULL , "Name" NVARCHAR(20) NOT NULL , "Frequency" NVARCHAR(1), "Day" INTEGER CS_INT, "Hour" INTEGER CS_INT, "UserSign" SMALLINT CS_INT, "NextDate" LONGDATE CS_LONGDATE, "Type" NVARCHAR(1) DEFAULT 'C', "SubOption" NVARCHAR(1) DEFAULT '1', "Interval" INTEGER CS_INT DEFAULT 1, "EndType" NVARCHAR(1) DEFAULT 'N', "MaxOccur" INTEGER CS_INT, "SeEndDat" LONGDATE CS_LONGDATE, "Sunday" NVARCHAR(1) DEFAULT 'N', "Monday" NVARCHAR(1) DEFAULT 'N', "Tuesday" NVARCHAR(1) DEFAULT 'N', "Wednesday" NVARCHAR(1) DEFAULT 'N', "Thursday" NVARCHAR(1) DEFAULT 'N', "Friday" NVARCHAR(1) DEFAULT 'N', "Saturday" NVARCHAR(1) DEFAULT 'N', "DayInMonth" INTEGER CS_INT, "Week" INTEGER CS_INT, "DayOfWeek" INTEGER CS_INT, "Month" INTEGER CS_INT, PRIMARY KEY ("Code")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OCYC_NAME" ON "TEST_AP"."OCYC" ( "Name" ASC )